SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
IF OBJECT_ID('flota.periodicidad_cobro','U') IS NULL CREATE TABLE flota.periodicidad_cobro(Cod_Periodicidad VARCHAR(1) NOT NULL PRIMARY KEY,Nombre VARCHAR(30) NOT NULL,DiasPeriodo INT NULL,Flg_Activo VARCHAR(1) NOT NULL DEFAULT('S'));
IF NOT EXISTS(SELECT 1 FROM flota.periodicidad_cobro WHERE Cod_Periodicidad='S') INSERT flota.periodicidad_cobro VALUES('S','Semanal',7,'S');
IF NOT EXISTS(SELECT 1 FROM flota.periodicidad_cobro WHERE Cod_Periodicidad='Q') INSERT flota.periodicidad_cobro VALUES('Q','Quincenal',15,'S');
IF NOT EXISTS(SELECT 1 FROM flota.periodicidad_cobro WHERE Cod_Periodicidad='M') INSERT flota.periodicidad_cobro VALUES('M','Mensual',NULL,'S');
IF COL_LENGTH('flota.contrato','Cod_Periodicidad') IS NULL ALTER TABLE flota.contrato ADD Cod_Periodicidad VARCHAR(1) NOT NULL CONSTRAINT DF_flota_contrato_periodicidad DEFAULT('S');
IF COL_LENGTH('flota.operacion_dia','FlgOrigen') IS NULL ALTER TABLE flota.operacion_dia ADD FlgOrigen VARCHAR(1) NOT NULL CONSTRAINT DF_flota_operacion_origen DEFAULT('O');
GO
IF OBJECT_ID('flota.p_contrato_crear','P') IS NOT NULL DROP PROCEDURE flota.p_contrato_crear;
GO
CREATE PROCEDURE flota.p_contrato_crear @id_empresa INT,@id_est CHAR(2),@IdVehiculo INT,@IdChofer INT,@Modalidad VARCHAR(1),@Periodicidad VARCHAR(1)='S',@FechaInicio DATE,@FechaFin DATE=NULL,@TarifaDia DECIMAL(18,2),@CobraDomingo BIT=0,@ControlKm BIT=0,@Observacion VARCHAR(300)=NULL,@Usuario INT,@Id INT OUTPUT,@Mensaje VARCHAR(250) OUTPUT AS BEGIN SET NOCOUNT ON;SET @Id=0;IF @TarifaDia<=0 BEGIN SET @Mensaje='La tarifa debe ser mayor a cero.';RETURN;END;IF NOT EXISTS(SELECT 1 FROM flota.periodicidad_cobro WHERE Cod_Periodicidad=@Periodicidad AND Flg_Activo='S') BEGIN SET @Mensaje='Periodicidad no valida.';RETURN;END;IF EXISTS(SELECT 1 FROM flota.contrato WHERE id_empresa=@id_empresa AND Id_Vehiculo=@IdVehiculo AND Flg_Estado='A') BEGIN SET @Mensaje='El vehiculo ya tiene un contrato activo.';RETURN;END;INSERT flota.contrato(id_empresa,id_est,Id_Vehiculo,Id_Chofer,Cod_Modalidad,Cod_Periodicidad,FechaInicio,FechaFin,TarifaDia,Flg_CobraDomingo,Flg_ControlKm,Observacion,Usu_Creacion) VALUES(@id_empresa,@id_est,@IdVehiculo,@IdChofer,@Modalidad,@Periodicidad,@FechaInicio,@FechaFin,@TarifaDia,CASE WHEN @CobraDomingo=1 THEN'S'ELSE'N'END,CASE WHEN @ControlKm=1 THEN'S'ELSE'N'END,@Observacion,@Usuario);SET @Id=SCOPE_IDENTITY();UPDATE flota.contrato SET Numero='ALQ-'+RIGHT('000000'+CONVERT(VARCHAR(6),@Id),6) WHERE Id_Contrato=@Id;SET @Mensaje='Contrato creado.';END
GO
IF OBJECT_ID('flota.medio_pago_alquiler','U') IS NULL CREATE TABLE flota.medio_pago_alquiler(Cod_MedioPago VARCHAR(2) NOT NULL PRIMARY KEY,Nombre VARCHAR(40) NOT NULL,Flg_Activo VARCHAR(1) NOT NULL DEFAULT('S'));
IF NOT EXISTS(SELECT 1 FROM flota.medio_pago_alquiler WHERE Cod_MedioPago='EF') INSERT flota.medio_pago_alquiler VALUES('EF','Efectivo','S');
IF NOT EXISTS(SELECT 1 FROM flota.medio_pago_alquiler WHERE Cod_MedioPago='YA') INSERT flota.medio_pago_alquiler VALUES('YA','Yape','S');
IF NOT EXISTS(SELECT 1 FROM flota.medio_pago_alquiler WHERE Cod_MedioPago='TR') INSERT flota.medio_pago_alquiler VALUES('TR','Transferencia','S');
GO
IF OBJECT_ID('flota.ReciboAlquiler','U') IS NULL
CREATE TABLE flota.ReciboAlquiler(Id_ReciboAlquiler INT IDENTITY(1,1) NOT NULL PRIMARY KEY,Numero VARCHAR(20) NULL,id_empresa INT NOT NULL,id_est CHAR(2) NOT NULL,Id_Contrato INT NOT NULL,FechaEmision DATE NOT NULL,FechaInicio DATE NOT NULL,FechaFin DATE NOT NULL,CantidadDias INT NOT NULL,TarifaDia DECIMAL(18,2) NOT NULL,ImporteTotal DECIMAL(18,2) NOT NULL,ImportePagado DECIMAL(18,2) NOT NULL DEFAULT(0),Saldo DECIMAL(18,2) NOT NULL,Estado VARCHAR(1) NOT NULL DEFAULT('P'),FlgOrigen VARCHAR(1) NOT NULL DEFAULT('O'),Observacion VARCHAR(300) NULL,Usu_Creacion INT NOT NULL,Fec_Creacion DATETIME NOT NULL DEFAULT(GETDATE()),Usu_Anula INT NULL,Fec_Anula DATETIME NULL,MotivoAnula VARCHAR(250) NULL,CONSTRAINT FK_flota_recibo_contrato FOREIGN KEY(Id_Contrato) REFERENCES flota.contrato(Id_Contrato),CONSTRAINT CK_flota_recibo_estado CHECK(Estado IN('P','A','C','X')),CONSTRAINT CK_flota_recibo_origen CHECK(FlgOrigen IN('O','M')));
GO
IF OBJECT_ID('flota.ReciboAlquilerDetalleDia','U') IS NULL
CREATE TABLE flota.ReciboAlquilerDetalleDia(Id_ReciboDetalle INT IDENTITY(1,1) NOT NULL PRIMARY KEY,Id_ReciboAlquiler INT NOT NULL,Id_OperacionDia INT NULL,Fecha DATE NOT NULL,TarifaDia DECIMAL(18,2) NOT NULL,ImporteDia DECIMAL(18,2) NOT NULL,FlgOrigen VARCHAR(1) NOT NULL,Observacion VARCHAR(250) NULL,CONSTRAINT FK_flota_recibo_det_cab FOREIGN KEY(Id_ReciboAlquiler) REFERENCES flota.ReciboAlquiler(Id_ReciboAlquiler),CONSTRAINT FK_flota_recibo_det_op FOREIGN KEY(Id_OperacionDia) REFERENCES flota.operacion_dia(Id_OperacionDia));
GO
IF OBJECT_ID('flota.PagoReciboAlquiler','U') IS NULL
CREATE TABLE flota.PagoReciboAlquiler(Id_PagoRecibo INT IDENTITY(1,1) NOT NULL PRIMARY KEY,id_empresa INT NOT NULL,id_est CHAR(2) NOT NULL,Id_ReciboAlquiler INT NOT NULL,FechaPago DATETIME NOT NULL,Importe DECIMAL(18,2) NOT NULL,MedioPago VARCHAR(2) NOT NULL,FotoVoucher VARCHAR(300) NULL,Observacion VARCHAR(300) NULL,FlgValidado VARCHAR(1) NOT NULL DEFAULT('N'),FlgEstado VARCHAR(1) NOT NULL DEFAULT('A'),Usu_Creacion INT NOT NULL,Fec_Creacion DATETIME NOT NULL DEFAULT(GETDATE()),CONSTRAINT FK_flota_pago_recibo FOREIGN KEY(Id_ReciboAlquiler) REFERENCES flota.ReciboAlquiler(Id_ReciboAlquiler),CONSTRAINT FK_flota_pago_medio FOREIGN KEY(MedioPago) REFERENCES flota.medio_pago_alquiler(Cod_MedioPago),CONSTRAINT CK_flota_pago_importe CHECK(Importe>0));
GO
IF TYPE_ID('flota.FechaSeleccionadaType') IS NULL EXEC('CREATE TYPE flota.FechaSeleccionadaType AS TABLE(Fecha DATE NOT NULL PRIMARY KEY)');
GO
IF OBJECT_ID('flota.p_ReciboAlquiler_Generar','P') IS NOT NULL DROP PROCEDURE flota.p_ReciboAlquiler_Generar;
GO
CREATE PROCEDURE flota.p_ReciboAlquiler_Generar @id_empresa INT,@id_est CHAR(2),@IdContrato INT,@FechaInicio DATE,@FechaFin DATE,@Observacion VARCHAR(300)=NULL,@Usuario INT,@IdRecibo INT OUTPUT,@Mensaje VARCHAR(300) OUTPUT
AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;SET @IdRecibo=0;BEGIN TRY BEGIN TRAN;DECLARE @Tarifa DECIMAL(18,2),@Origen VARCHAR(1)='O';SELECT @Tarifa=TarifaDia FROM flota.contrato WITH(UPDLOCK,HOLDLOCK) WHERE Id_Contrato=@IdContrato AND id_empresa=@id_empresa AND id_est=@id_est AND Flg_Estado='A';IF @Tarifa IS NULL RAISERROR('Contrato activo no encontrado.',16,1);IF @FechaFin<@FechaInicio RAISERROR('El rango de fechas no es valido.',16,1);DECLARE @Dias TABLE(IdOperacion INT,Fecha DATE,Importe DECIMAL(18,2),Origen VARCHAR(1));INSERT @Dias SELECT o.Id_OperacionDia,o.Fecha,o.ImporteGenerado,o.FlgOrigen FROM flota.operacion_dia o WHERE o.Id_Contrato=@IdContrato AND o.Fecha BETWEEN @FechaInicio AND @FechaFin AND o.Flg_Cobrable='S' AND o.ImporteGenerado>0 AND NOT EXISTS(SELECT 1 FROM flota.ReciboAlquilerDetalleDia d JOIN flota.ReciboAlquiler r ON r.Id_ReciboAlquiler=d.Id_ReciboAlquiler WHERE d.Id_OperacionDia=o.Id_OperacionDia AND r.Estado<>'X');IF NOT EXISTS(SELECT 1 FROM @Dias) RAISERROR('No hay dias cobrables disponibles en el periodo.',16,1);DECLARE @Cantidad INT,@Total DECIMAL(18,2);SELECT @Cantidad=COUNT(*),@Total=SUM(Importe) FROM @Dias;INSERT flota.ReciboAlquiler(id_empresa,id_est,Id_Contrato,FechaEmision,FechaInicio,FechaFin,CantidadDias,TarifaDia,ImporteTotal,Saldo,FlgOrigen,Observacion,Usu_Creacion) VALUES(@id_empresa,@id_est,@IdContrato,CAST(GETDATE() AS DATE),(SELECT MIN(Fecha) FROM @Dias),(SELECT MAX(Fecha) FROM @Dias),@Cantidad,@Tarifa,@Total,@Total,@Origen,@Observacion,@Usuario);SET @IdRecibo=SCOPE_IDENTITY();UPDATE flota.ReciboAlquiler SET Numero='RA-'+RIGHT('00000000'+CONVERT(VARCHAR(8),@IdRecibo),8) WHERE Id_ReciboAlquiler=@IdRecibo;INSERT flota.ReciboAlquilerDetalleDia(Id_ReciboAlquiler,Id_OperacionDia,Fecha,TarifaDia,ImporteDia,FlgOrigen) SELECT @IdRecibo,IdOperacion,Fecha,@Tarifa,Importe,Origen FROM @Dias;COMMIT;SET @Mensaje='Recibo generado correctamente.';END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK;SET @Mensaje=ERROR_MESSAGE();SET @IdRecibo=0;END CATCH;END
GO
IF OBJECT_ID('flota.p_ReciboAlquiler_GenerarManual','P') IS NOT NULL DROP PROCEDURE flota.p_ReciboAlquiler_GenerarManual;
GO
CREATE PROCEDURE flota.p_ReciboAlquiler_GenerarManual @id_empresa INT,@id_est CHAR(2),@IdContrato INT,@Fechas flota.FechaSeleccionadaType READONLY,@TarifaDia DECIMAL(18,2),@ModoAgrupacion VARCHAR(1),@Observacion VARCHAR(300)=NULL,@Usuario INT,@CantidadRecibos INT OUTPUT,@Mensaje VARCHAR(300) OUTPUT
AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;SET @CantidadRecibos=0;BEGIN TRY BEGIN TRAN;IF @TarifaDia<=0 RAISERROR('La tarifa debe ser mayor a cero.',16,1);IF NOT EXISTS(SELECT 1 FROM flota.contrato WHERE Id_Contrato=@IdContrato AND id_empresa=@id_empresa AND id_est=@id_est AND Flg_Estado='A') RAISERROR('Contrato activo no encontrado.',16,1);IF NOT EXISTS(SELECT 1 FROM @Fechas) RAISERROR('Selecciona al menos un dia.',16,1);IF EXISTS(SELECT 1 FROM @Fechas f JOIN flota.ReciboAlquilerDetalleDia d ON d.Fecha=f.Fecha JOIN flota.ReciboAlquiler r ON r.Id_ReciboAlquiler=d.Id_ReciboAlquiler WHERE r.Id_Contrato=@IdContrato AND r.Estado<>'X') RAISERROR('Uno o mas dias ya pertenecen a un recibo activo.',16,1);DECLARE @Ops TABLE(Fecha DATE PRIMARY KEY,IdOperacion INT);MERGE flota.operacion_dia AS t USING(SELECT Fecha FROM @Fechas)s ON t.Id_Contrato=@IdContrato AND t.Fecha=s.Fecha WHEN MATCHED THEN UPDATE SET Flg_Trabajo='S',Cod_Motivo='TRA',Flg_Cobrable='S',ImporteGenerado=@TarifaDia,FlgOrigen='M',Observacion=COALESCE(@Observacion,t.Observacion),Usu_Modif=@Usuario,Fec_Modif=GETDATE() WHEN NOT MATCHED THEN INSERT(id_empresa,id_est,Id_Contrato,Fecha,Flg_Trabajo,Cod_Motivo,Flg_Cobrable,ImporteGenerado,FlgOrigen,Observacion,Usu_Creacion) VALUES(@id_empresa,@id_est,@IdContrato,s.Fecha,'S','TRA','S',@TarifaDia,'M',@Observacion,@Usuario);INSERT @Ops SELECT o.Fecha,o.Id_OperacionDia FROM flota.operacion_dia o JOIN @Fechas f ON f.Fecha=o.Fecha WHERE o.Id_Contrato=@IdContrato;DECLARE @Grupos TABLE(Grupo INT,FechaInicio DATE,FechaFin DATE,Cantidad INT);IF @ModoAgrupacion='U' INSERT @Grupos SELECT 1,MIN(Fecha),MAX(Fecha),COUNT(*) FROM @Fechas;ELSE BEGIN DECLARE @f DATE,@prev DATE=NULL,@g INT=0;DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT Fecha FROM @Fechas ORDER BY Fecha;OPEN c;FETCH NEXT FROM c INTO @f;WHILE @@FETCH_STATUS=0 BEGIN IF @prev IS NULL OR DATEDIFF(DAY,@prev,@f)>1 SET @g=@g+1;IF EXISTS(SELECT 1 FROM @Grupos WHERE Grupo=@g) UPDATE @Grupos SET FechaFin=@f,Cantidad=Cantidad+1 WHERE Grupo=@g ELSE INSERT @Grupos VALUES(@g,@f,@f,1);SET @prev=@f;FETCH NEXT FROM c INTO @f;END CLOSE c;DEALLOCATE c;END DECLARE @Grupo INT,@Ini DATE,@Fin DATE,@Cant INT,@Id INT;DECLARE g CURSOR LOCAL FAST_FORWARD FOR SELECT Grupo,FechaInicio,FechaFin,Cantidad FROM @Grupos ORDER BY Grupo;OPEN g;FETCH NEXT FROM g INTO @Grupo,@Ini,@Fin,@Cant;WHILE @@FETCH_STATUS=0 BEGIN INSERT flota.ReciboAlquiler(id_empresa,id_est,Id_Contrato,FechaEmision,FechaInicio,FechaFin,CantidadDias,TarifaDia,ImporteTotal,Saldo,FlgOrigen,Observacion,Usu_Creacion) VALUES(@id_empresa,@id_est,@IdContrato,CAST(GETDATE() AS DATE),@Ini,@Fin,@Cant,@TarifaDia,@Cant*@TarifaDia,@Cant*@TarifaDia,'M',@Observacion,@Usuario);SET @Id=SCOPE_IDENTITY();UPDATE flota.ReciboAlquiler SET Numero='RA-'+RIGHT('00000000'+CONVERT(VARCHAR(8),@Id),8) WHERE Id_ReciboAlquiler=@Id;INSERT flota.ReciboAlquilerDetalleDia(Id_ReciboAlquiler,Id_OperacionDia,Fecha,TarifaDia,ImporteDia,FlgOrigen,Observacion) SELECT @Id,o.IdOperacion,o.Fecha,@TarifaDia,@TarifaDia,'M',@Observacion FROM @Ops o WHERE(@ModoAgrupacion='U' OR o.Fecha BETWEEN @Ini AND @Fin);SET @CantidadRecibos=@CantidadRecibos+1;FETCH NEXT FROM g INTO @Grupo,@Ini,@Fin,@Cant;END CLOSE g;DEALLOCATE g;COMMIT;SET @Mensaje=CONVERT(VARCHAR(10),@CantidadRecibos)+' recibo(s) generado(s).';SELECT Id_ReciboAlquiler,Numero,FechaInicio,FechaFin,ImporteTotal FROM flota.ReciboAlquiler WHERE Id_Contrato=@IdContrato AND Fec_Creacion>=DATEADD(MINUTE,-1,GETDATE()) AND Usu_Creacion=@Usuario ORDER BY Id_ReciboAlquiler;END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK;SET @Mensaje=ERROR_MESSAGE();SET @CantidadRecibos=0;END CATCH;END
GO
IF OBJECT_ID('flota.p_PagoReciboAlquiler_Registrar','P') IS NOT NULL DROP PROCEDURE flota.p_PagoReciboAlquiler_Registrar;
GO
CREATE PROCEDURE flota.p_PagoReciboAlquiler_Registrar @id_empresa INT,@id_est CHAR(2),@IdReciboAlquiler INT,@FechaPago DATETIME,@Importe DECIMAL(18,2),@MedioPago VARCHAR(2),@FotoVoucher VARCHAR(300)=NULL,@Observacion VARCHAR(300)=NULL,@FlgValidado VARCHAR(1)='N',@Usuario INT,@IdPago INT OUTPUT,@Mensaje VARCHAR(300) OUTPUT
AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;SET @IdPago=0;BEGIN TRY BEGIN TRAN;DECLARE @Saldo DECIMAL(18,2);SELECT @Saldo=Saldo FROM flota.ReciboAlquiler WITH(UPDLOCK,HOLDLOCK) WHERE Id_ReciboAlquiler=@IdReciboAlquiler AND id_empresa=@id_empresa AND id_est=@id_est AND Estado IN('P','A');IF @Saldo IS NULL RAISERROR('Recibo no disponible para pago.',16,1);IF @Importe<=0 OR @Importe>@Saldo RAISERROR('El importe debe ser mayor a cero y no superar el saldo.',16,1);IF NOT EXISTS(SELECT 1 FROM flota.medio_pago_alquiler WHERE Cod_MedioPago=@MedioPago AND Flg_Activo='S') RAISERROR('Medio de pago no valido.',16,1);INSERT flota.PagoReciboAlquiler(id_empresa,id_est,Id_ReciboAlquiler,FechaPago,Importe,MedioPago,FotoVoucher,Observacion,FlgValidado,Usu_Creacion) VALUES(@id_empresa,@id_est,@IdReciboAlquiler,@FechaPago,@Importe,@MedioPago,@FotoVoucher,@Observacion,@FlgValidado,@Usuario);SET @IdPago=SCOPE_IDENTITY();UPDATE flota.ReciboAlquiler SET ImportePagado=ImportePagado+@Importe,Saldo=Saldo-@Importe,Estado=CASE WHEN Saldo-@Importe=0 THEN'C' ELSE'A' END WHERE Id_ReciboAlquiler=@IdReciboAlquiler;COMMIT;SET @Mensaje='Pago registrado contra el recibo.';END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK;SET @Mensaje=ERROR_MESSAGE();SET @IdPago=0;END CATCH;END
GO
IF OBJECT_ID('flota.p_ReciboAlquiler_ListarPorContrato','P') IS NOT NULL DROP PROCEDURE flota.p_ReciboAlquiler_ListarPorContrato;
GO
CREATE PROCEDURE flota.p_ReciboAlquiler_ListarPorContrato @id_empresa INT,@id_est CHAR(2),@IdContrato INT,@Anio INT=NULL,@Mes INT=NULL AS BEGIN SET NOCOUNT ON;SELECT r.Id_ReciboAlquiler,r.Numero,r.FechaEmision,r.FechaInicio,r.FechaFin,r.CantidadDias,r.TarifaDia,r.ImporteTotal,r.ImportePagado,r.Saldo,r.Estado,CASE r.Estado WHEN'P'THEN'Pendiente' WHEN'A'THEN'Parcial' WHEN'C'THEN'Pagado' ELSE'Anulado' END EstadoTexto,r.FlgOrigen,ISNULL(r.Observacion,'') Observacion FROM flota.ReciboAlquiler r WHERE r.id_empresa=@id_empresa AND r.id_est=@id_est AND r.Id_Contrato=@IdContrato AND(@Anio IS NULL OR YEAR(r.FechaInicio)=@Anio)AND(@Mes IS NULL OR MONTH(r.FechaInicio)=@Mes)ORDER BY r.FechaInicio DESC,r.Id_ReciboAlquiler DESC;END
GO
IF OBJECT_ID('flota.p_ReciboAlquiler_ObtenerDetalle','P') IS NOT NULL DROP PROCEDURE flota.p_ReciboAlquiler_ObtenerDetalle;
GO
CREATE PROCEDURE flota.p_ReciboAlquiler_ObtenerDetalle @id_empresa INT,@id_est CHAR(2),@IdReciboAlquiler INT AS BEGIN SET NOCOUNT ON;SELECT r.*,c.Numero Contrato,v.Placa,ISNULL(ch.Nombres,'') Chofer FROM flota.ReciboAlquiler r JOIN flota.contrato c ON c.Id_Contrato=r.Id_Contrato JOIN flota.vehiculo v ON v.Id_Vehiculo=c.Id_Vehiculo JOIN flota.chofer ch ON ch.Id_Chofer=c.Id_Chofer WHERE r.Id_ReciboAlquiler=@IdReciboAlquiler AND r.id_empresa=@id_empresa AND r.id_est=@id_est;SELECT d.Id_ReciboDetalle,d.Id_OperacionDia,d.Fecha,d.TarifaDia,d.ImporteDia,d.FlgOrigen,ISNULL(d.Observacion,'') Observacion FROM flota.ReciboAlquilerDetalleDia d WHERE d.Id_ReciboAlquiler=@IdReciboAlquiler ORDER BY d.Fecha;SELECT p.Id_PagoRecibo,p.FechaPago,p.Importe,p.MedioPago,m.Nombre MedioPagoTexto,ISNULL(p.FotoVoucher,'') FotoVoucher,ISNULL(p.Observacion,'') Observacion,p.FlgValidado FROM flota.PagoReciboAlquiler p JOIN flota.medio_pago_alquiler m ON m.Cod_MedioPago=p.MedioPago WHERE p.Id_ReciboAlquiler=@IdReciboAlquiler AND p.FlgEstado='A' ORDER BY p.FechaPago,p.Id_PagoRecibo;END
GO
IF OBJECT_ID('flota.p_AdminCalendario_Obtener','P') IS NOT NULL DROP PROCEDURE flota.p_AdminCalendario_Obtener;
GO
CREATE PROCEDURE flota.p_AdminCalendario_Obtener @id_empresa INT,@id_est CHAR(2),@IdContrato INT,@Anio INT,@Mes INT AS BEGIN SET NOCOUNT ON;SELECT c.Id_Contrato,c.Numero,v.Placa,ISNULL(v.MarcaTexto,'')+' '+ISNULL(v.ModeloTexto,'') Vehiculo,ISNULL(ch.Nombres,'') Chofer,c.Cod_Modalidad,c.TarifaDia,c.Cod_Periodicidad FROM flota.contrato c JOIN flota.vehiculo v ON v.Id_Vehiculo=c.Id_Vehiculo JOIN flota.chofer ch ON ch.Id_Chofer=c.Id_Chofer WHERE c.Id_Contrato=@IdContrato AND c.id_empresa=@id_empresa AND c.id_est=@id_est;SELECT o.Id_OperacionDia,o.Fecha,o.Flg_Trabajo,o.Cod_Motivo,m.Nombre Motivo,o.Flg_Cobrable,o.ImporteGenerado,ISNULL(o.KmRecorrido,0) KmRecorrido,o.FlgOrigen,CASE WHEN EXISTS(SELECT 1 FROM flota.ReciboAlquilerDetalleDia d JOIN flota.ReciboAlquiler r ON r.Id_ReciboAlquiler=d.Id_ReciboAlquiler WHERE d.Id_OperacionDia=o.Id_OperacionDia AND r.Estado<>'X')THEN'S'ELSE'N'END TieneRecibo FROM flota.operacion_dia o JOIN flota.motivo_dia m ON m.Cod_Motivo=o.Cod_Motivo WHERE o.Id_Contrato=@IdContrato AND YEAR(o.Fecha)=@Anio AND MONTH(o.Fecha)=@Mes ORDER BY o.Fecha;SELECT Cod_MedioPago Codigo,Nombre FROM flota.medio_pago_alquiler WHERE Flg_Activo='S' ORDER BY Nombre;END
GO
IF OBJECT_ID('flota.p_Contrato_Admin_Listar','P') IS NOT NULL DROP PROCEDURE flota.p_Contrato_Admin_Listar;
GO
CREATE PROCEDURE flota.p_Contrato_Admin_Listar @id_empresa INT,@id_est CHAR(2) AS BEGIN SET NOCOUNT ON;SELECT c.Id_Contrato,c.Numero,v.Placa,ISNULL(ch.Nombres,'') Chofer,c.Cod_Modalidad,m.Nombre Modalidad,c.TarifaDia,c.Cod_Periodicidad,c.FechaInicio,c.FechaFin,c.Flg_Estado,ISNULL(x.Total,0) TotalRecibos,ISNULL(x.Pagado,0) TotalPagado,ISNULL(x.Saldo,0) Saldo FROM flota.contrato c JOIN flota.vehiculo v ON v.Id_Vehiculo=c.Id_Vehiculo JOIN flota.chofer ch ON ch.Id_Chofer=c.Id_Chofer JOIN flota.modalidad m ON m.Cod_Modalidad=c.Cod_Modalidad OUTER APPLY(SELECT SUM(ImporteTotal) Total,SUM(ImportePagado) Pagado,SUM(Saldo) Saldo FROM flota.ReciboAlquiler r WHERE r.Id_Contrato=c.Id_Contrato AND r.Estado<>'X')x WHERE c.id_empresa=@id_empresa AND c.id_est=@id_est ORDER BY c.Flg_Estado,c.Id_Contrato DESC;END
GO
